def range_bitwise_and(left, right):
    result = left
    for x in range(left + 1, right + 1):
        result &= x
        if result == 0:
            break
    return result

def range_bitwise_and(left, right):
    shift = 0
    while left != right:
        left, right = left >> 1, right >> 1
        shift += 1
    return left << shift

def range_bitwise_and(left, right):
    while right > left:
        right &= right - 1
    return right
